using System;
using System.Collections.Concurrent;
using System.IO;
using System.Net;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;
using System.Threading.Tasks;

namespace ApiServer
{
    public enum CircuitState { Closed, Open, HalfOpen }

    public class CircuitBreaker
    {
        private CircuitState _state = CircuitState.Closed;
        private int _failureCount = 0;
        private readonly int _threshold = 3;
        private DateTime _lastFailure = DateTime.MinValue;
        private readonly TimeSpan _timeout = TimeSpan.FromSeconds(30);
        private readonly object _lock = new object();

        public bool AllowRequest()
        {
            lock (_lock)
            {
                if (_state == CircuitState.Closed) return true;
                if (_state == CircuitState.Open)
                {
                    if (DateTime.UtcNow - _lastFailure > _timeout)
                    {
                        _state = CircuitState.HalfOpen;
                        return true;
                    }
                    return false;
                }
                return true; // HalfOpen allows one request
            }
        }

        public void RecordSuccess()
        {
            lock (_lock) { _state = CircuitState.Closed; _failureCount = 0; }
        }

        public void RecordFailure()
        {
            lock (_lock)
            {
                _failureCount++;
                _lastFailure = DateTime.UtcNow;
                if (_failureCount >= _threshold) _state = CircuitState.Open;
            }
        }
    }

    public class ContentRenderer
    {
        private readonly string _templateRoot;
        private readonly ConcurrentDictionary<string, string> _cache;

        public ContentRenderer(string templateRoot)
        {
            _templateRoot = Path.GetFullPath(templateRoot);
            _cache = new ConcurrentDictionary<string, string>();
        }

        public string RenderTemplate(string templateName, ConcurrentDictionary<string, string> variables)
        {
            string content = LoadTemplate(templateName);
            content = SubstituteVariables(content, variables);
            content = ProcessIncludes(content);
            return content;
        }

        private string LoadTemplate(string name)
        {
            if (_cache.TryGetValue(name, out string cached)) return cached;
            string safeName = SanitizeFileName(name);
            string path = Path.Combine(_templateRoot, safeName);
            if (!File.Exists(path)) return "<!-- template not found -->";
            string content = File.ReadAllText(path);
            _cache[name] = content;
            return content;
        }

        private string SanitizeFileName(string name)
        {
            // Remove path traversal attempts
            name = name.Replace("..", "").Replace("/", "").Replace("\\", "");
            return Regex.Replace(name, @"[^a-zA-Z0-9_\-\.]", "");
        }

        private string SubstituteVariables(string content, ConcurrentDictionary<string, string> variables)
        {
            foreach (var kvp in variables)
            {
                string placeholder = "{{" + kvp.Key + "}}";
                content = content.Replace(placeholder, kvp.Value);
            }
            return content;
        }

        private string ProcessIncludes(string content)
        {
            // Process SSI-style includes: <!--#include virtual="filename" -->
            var pattern = @"<!--#include\s+virtual=""([^""]+)""\s*-->";
            return Regex.Replace(content, pattern, match =>
            {
                string includeFile = match.Groups[1].Value;
                string safeName = SanitizeFileName(includeFile);
                string path = Path.Combine(_templateRoot, safeName);
                if (File.Exists(path)) return File.ReadAllText(path);
                return "<!-- include not found -->";
            });
        }
    }

    public class ApiServer
    {
        private readonly HttpListener _listener;
        private readonly CircuitBreaker _circuitBreaker;
        private readonly ContentRenderer _renderer;
        private readonly ConcurrentDictionary<string, string> _userVariables;

        public ApiServer(string prefix, string templateRoot)
        {
            _listener = new HttpListener();
            _listener.Prefixes.Add(prefix);
            _circuitBreaker = new CircuitBreaker();
            _renderer = new ContentRenderer(templateRoot);
            _userVariables = new ConcurrentDictionary<string, string>();
        }

        public async Task StartAsync(CancellationToken ct)
        {
            _listener.Start();
            while (!ct.IsCancellationRequested)
            {
                var context = await _listener.GetContextAsync();
                _ = Task.Run(() => HandleRequest(context), ct);
            }
        }

        private void HandleRequest(HttpListenerContext context)
        {
            var request = context.Request;
            var response = context.Response;

            try
            {
                if (!_circuitBreaker.AllowRequest())
                {
                    SendResponse(response, 503, "{\"error\":\"Service unavailable\"}");
                    return;
                }

                string path = request.Url.AbsolutePath;

                if (path == "/api/render" && request.HttpMethod == "POST")
                    HandleRender(request, response);
                else if (path == "/api/variables" && request.HttpMethod == "PUT")
                    HandleSetVariable(request, response);
                else if (path == "/api/health")
                    SendResponse(response, 200, "{\"status\":\"ok\"}");
                else
                    SendResponse(response, 404, "{\"error\":\"not found\"}");

                _circuitBreaker.RecordSuccess();
            }
            catch (Exception)
            {
                _circuitBreaker.RecordFailure();
                SendResponse(response, 500, "{\"error\":\"internal error\"}");
            }
        }

        private void HandleSetVariable(HttpListenerRequest request, HttpListenerResponse response)
        {
            using (var reader = new StreamReader(request.InputStream, request.ContentEncoding))
            {
                string body = reader.ReadToEnd();
                // Simple key=value format
                var parts = body.Split('=');
                if (parts.Length == 2)
                {
                    string key = parts[0].Trim();
                    string value = parts[1].Trim();
                    // Validate key format
                    if (Regex.IsMatch(key, @"^[a-zA-Z_][a-zA-Z0-9_]*$"))
                    {
                        _userVariables[key] = value;
                        SendResponse(response, 200, "{\"status\":\"set\"}");
                        return;
                    }
                }
            }
            SendResponse(response, 400, "{\"error\":\"invalid format\"}");
        }

        private void HandleRender(HttpListenerRequest request, HttpListenerResponse response)
        {
            using (var reader = new StreamReader(request.InputStream, request.ContentEncoding))
            {
                string templateName = reader.ReadToEnd().Trim();
                string result = _renderer.RenderTemplate(templateName, _userVariables);
                SendResponse(response, 200, result);
            }
        }

        private void SendResponse(HttpListenerResponse response, int statusCode, string body)
        {
            response.StatusCode = statusCode;
            response.ContentType = "application/json";
            byte[] buffer = Encoding.UTF8.GetBytes(body);
            response.ContentLength64 = buffer.Length;
            response.OutputStream.Write(buffer, 0, buffer.Length);
            response.Close();
        }
    }

    class Program
    {
        static async Task Main(string[] args)
        {
            var server = new ApiServer("http://localhost:8080/", "./templates");
            using var cts = new CancellationTokenSource();
            Console.CancelKeyPress += (s, e) => { e.Cancel = true; cts.Cancel(); };
            await server.StartAsync(cts.Token);
        }
    }
}
